import {segmentEnergy} from './engine.mjs';
export function distance(a,b){const r=Math.PI/180,dlat=(b.lat-a.lat)*r,dlon=(b.lng-a.lng)*r;const h=Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlon/2)**2;return 6371*2*Math.asin(Math.min(1,Math.sqrt(h)));}
export function sampleRoad(road,max=100){const coords=road.geometry.coordinates.map(([lng,lat])=>({lat,lng}));const cum=[0];for(let i=1;i<coords.length;i++)cum.push(cum.at(-1)+distance(coords[i-1],coords[i]));const total=cum.at(-1);if(!total)throw Error('Route has no measurable length.');const count=Math.min(max,Math.max(2,Math.ceil(road.distance/1000/2)+1));let j=1;return Array.from({length:count},(_,i)=>{const at=total*i/(count-1);while(j<cum.length-1&&cum[j]<at)j++;const f=(at-cum[j-1])/(cum[j]-cum[j-1]||1);return {lat:coords[j-1].lat+(coords[j].lat-coords[j-1].lat)*f,lng:coords[j-1].lng+(coords[j].lng-coords[j-1].lng)*f,km:road.distance/1000*i/(count-1)};});}
const cache=new Map();
export async function terrainRoad(road,{signal}={}){if(road.profile)return road;const points=sampleRoad(road);const key=points.map(p=>`${p.lat.toFixed(5)},${p.lng.toFixed(5)}`).join(';');let heights=cache.get(key);if(!heights){const u=new URL('https://api.open-meteo.com/v1/elevation');u.searchParams.set('latitude',points.map(p=>p.lat.toFixed(5)).join(','));u.searchParams.set('longitude',points.map(p=>p.lng.toFixed(5)).join(','));const res=await fetch(u,{signal});if(!res.ok)throw Error(res.status===429?'Free elevation service rate limit reached. Wait a minute before retrying; no unchecked plan will be exported.':`Elevation service unavailable (HTTP ${res.status}). Cannot validate the battery reserve; please retry.`);heights=(await res.json()).elevation;if(!Array.isArray(heights)||heights.length!==points.length||heights.some(x=>!Number.isFinite(x)))throw Error('Elevation data is incomplete; no reserve-checked plan can be produced.');if(cache.size>40)cache.clear();cache.set(key,heights);}return {...road,profile:points.map((p,i)=>({...p,elevation:heights[i]}))};}
export function terrainEnergy(road,s,startSoc=s.battery){if(!Array.isArray(road.profile)||road.profile.length<2||road.profile.some((p,i,a)=>!Number.isFinite(p.km)||!Number.isFinite(p.elevation)||i>0&&p.km<a[i-1].km)||road.profile[0].km!==0||Math.abs(road.profile.at(-1).km-road.distance/1000)>.01)throw Error('Terrain profile is incomplete; no reserve-checked plan can be produced.');let energy=0,ascent=0,descent=0;const trace=[{km:0,soc:startSoc}];for(let i=1;i<road.profile.length;i++){const a=road.profile[i-1],b=road.profile[i],rise=b.elevation-a.elevation;ascent+=Math.max(0,rise);descent+=Math.max(0,-rise);energy+=segmentEnergy(b.km-a.km,rise,s);trace.push({km:b.km,soc:startSoc-energy/s.capacity*100});}return {energy,ascent,descent,trace,arrival:trace.at(-1).soc,minimum:Math.min(...trace.map(p=>p.soc))};}
